const body = $json.body ?? {};

const date = body.date;
const start = body.start;
const durationMinutes = body.durationMinutes;
const customer = body.customer ?? {};

function error(code, message, field, received = undefined) {
  const response = {
    valid: false,
    statusCode: 400,
    error: {
      code,
      message,
      field
    }
  };

  if (received !== undefined) {
    response.error.received = received;
  }

  return [{ json: response }];
}

// -------------------------
// Date
// -------------------------

if (!date) {
  return error(
    "MISSING_DATE",
    "Date is required.",
    "date"
  );
}

const datePattern = /^\d{4}-\d{2}-\d{2}$/;

if (!datePattern.test(date)) {
  return error(
    "INVALID_DATE_FORMAT",
    "Date must be in YYYY-MM-DD format.",
    "date",
    date
  );
}

const [year, month, day] = date.split("-").map(Number);

const parsedDate = new Date(
  Date.UTC(year, month - 1, day)
);

const isRealDate =
  parsedDate.getUTCFullYear() === year &&
  parsedDate.getUTCMonth() === month - 1 &&
  parsedDate.getUTCDate() === day;

if (!isRealDate) {
  return error(
    "INVALID_DATE",
    "The supplied date does not exist.",
    "date",
    date
  );
}
// Get today's date in the business timezone.
const businessTimezone = "Asia/Karachi";

const todayInBusinessTimezone =
  new Intl.DateTimeFormat("en-CA", {
    timeZone: businessTimezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).format(new Date());

if (date < todayInBusinessTimezone) {
  return error(
    "DATE_IN_PAST",
    "Appointments cannot be booked for a date in the past.",
    "date",
    date
  );
}
// -------------------------
// Start time
// -------------------------

if (!start) {
  return error(
    "MISSING_START_TIME",
    "Start time is required.",
    "start"
  );
}

const timePattern = /^([01]\d|2[0-3]):[0-5]\d$/;

if (!timePattern.test(start)) {
  return error(
    "INVALID_START_TIME",
    "Start time must use HH:MM format.",
    "start",
    start
  );
}
const now = new Date();

const currentTimeInBusinessTimezone =
  new Intl.DateTimeFormat("en-GB", {
    timeZone: businessTimezone,
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  }).format(now);

if (
  date === todayInBusinessTimezone &&
  start <= currentTimeInBusinessTimezone
) {
  return error(
    "START_TIME_IN_PAST",
    "The requested appointment time has already passed.",
    "start",
    start
  );
}
// -------------------------
// Duration
// -------------------------

if (
  durationMinutes === undefined ||
  durationMinutes === null ||
  durationMinutes === ""
) {
  return error(
    "MISSING_DURATION",
    "durationMinutes is required.",
    "durationMinutes"
  );
}

const duration = Number(durationMinutes);

if (!Number.isInteger(duration)) {
  return error(
    "INVALID_DURATION",
    "durationMinutes must be an integer.",
    "durationMinutes",
    durationMinutes
  );
}

const allowedDurations = [
  15,
  30,
  45,
  60,
  90,
  120
];

if (!allowedDurations.includes(duration)) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: {
        code: "UNSUPPORTED_DURATION",
        message: "Unsupported appointment duration.",
        field: "durationMinutes",
        received: duration,
        allowed: allowedDurations
      }
    }
  }];
}

// -------------------------
// Customer
// -------------------------

if (!customer.name) {
  return error(
    "MISSING_CUSTOMER_NAME",
    "Customer name is required.",
    "customer.name"
  );
}

const customerName =
  String(customer.name).trim();

if (customerName.length < 2) {
  return error(
    "INVALID_CUSTOMER_NAME",
    "Customer name must contain at least 2 characters.",
    "customer.name",
    customer.name
  );
}

// -------------------------
// Phone
// -------------------------

if (!customer.phone) {
  return error(
    "MISSING_CUSTOMER_PHONE",
    "Customer phone is required.",
    "customer.phone"
  );
}

const phone =
  String(customer.phone).trim();

if (phone.length < 7) {
  return error(
    "INVALID_CUSTOMER_PHONE",
    "Customer phone number is invalid.",
    "customer.phone",
    customer.phone
  );
}

// -------------------------
// Email
// -------------------------

if (customer.email) {
  const email =
    String(customer.email).trim();

  const emailPattern =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailPattern.test(email)) {
    return error(
      "INVALID_CUSTOMER_EMAIL",
      "Customer email address is invalid.",
      "customer.email",
      customer.email
    );
  }
}

// -------------------------
// Success
// -------------------------

return [{
  json: {
    valid: true,
    statusCode: 200,

    booking: {
      date,
      start,
      durationMinutes: duration,

      customer: {
        name: customerName,
        phone,
        email: customer.email
          ? String(customer.email).trim()
          : null
      }
    }
  }
}];

const booking = $json.booking;

const config = {
  timezone: "Asia/Karachi",

  defaultAppointmentDurationMinutes: 60,

  allowedDurations: [
    15,
    30,
    45,
    60,
    90,
    120
  ],

  bufferMinutes: 15,

  workingHours: {
    monday: [{ start: "09:00", end: "17:00" }],
    tuesday: [{ start: "09:00", end: "17:00" }],
    wednesday: [{ start: "09:00", end: "17:00" }],
    thursday: [{ start: "09:00", end: "17:00" }],
    friday: [{ start: "09:00", end: "17:00" }],
    saturday: [],
    sunday: []
  }
};

return [{
  json: {
    booking,
    config
  }
}];

const { booking, config } = $json;

const {
  date,
  start,
  durationMinutes
} = booking;

const dayNames = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday"
];

const requestedDate =
  new Date(`${date}T00:00:00`);

const dayName =
  dayNames[requestedDate.getDay()];

const periods =
  config.workingHours[dayName] || [];

if (periods.length === 0) {
  return [{
    json: {
      valid: false,
      statusCode: 409,
      error: {
        code: "BUSINESS_CLOSED",
        message: "The business is closed on the requested date."
      }
    }
  }];
}

const [startHour, startMinute] =
  start.split(":").map(Number);

const startMinutes =
  startHour * 60 + startMinute;

const endMinutes =
  startMinutes + durationMinutes;

const fitsInsideWorkingHours =
  periods.some(period => {

    const [periodStartHour, periodStartMinute] =
      period.start.split(":").map(Number);

    const [periodEndHour, periodEndMinute] =
      period.end.split(":").map(Number);

    const periodStart =
      periodStartHour * 60 + periodStartMinute;

    const periodEnd =
      periodEndHour * 60 + periodEndMinute;

    return (
      startMinutes >= periodStart &&
      endMinutes <= periodEnd
    );
  });

if (!fitsInsideWorkingHours) {
  return [{
    json: {
      valid: false,
      statusCode: 409,
      error: {
        code: "OUTSIDE_BUSINESS_HOURS",
        message: "The requested appointment falls outside business hours."
      }
    }
  }];
}

const endHour =
  Math.floor(endMinutes / 60);

const endMinute =
  endMinutes % 60;

const end =
  `${String(endHour).padStart(2, "0")}:${String(endMinute).padStart(2, "0")}`;

return [{
  json: {
    valid: true,
    statusCode: 200,

    booking: {
      ...booking,
      end
    },

    config,

    day: dayName,

    requestedStartDateTime:
      `${date}T${start}:00+05:00`,

    requestedEndDateTime:
      `${date}T${end}:00+05:00`
  }
}];

const bookingData =
  $("Validate Requested Slot").first().json;

const events =
  $input.all();

const requestedStart =
  new Date(
    bookingData.requestedStartDateTime
  );

const requestedEnd =
  new Date(
    bookingData.requestedEndDateTime
  );

const bufferMinutes =
  bookingData.config.bufferMinutes ?? 0;

const bufferMilliseconds =
  bufferMinutes * 60 * 1000;

const conflicts = [];

for (const item of events) {
  const event = item.json;

  if (
    !event.start?.dateTime ||
    !event.end?.dateTime
  ) {
    continue;
  }

  const eventStart =
    new Date(event.start.dateTime);

  const eventEnd =
    new Date(event.end.dateTime);

  const blockedEventEnd =
    new Date(
      eventEnd.getTime() +
      bufferMilliseconds
    );

  const overlaps =
    eventStart < requestedEnd &&
    blockedEventEnd > requestedStart;

  if (overlaps) {
    conflicts.push({
      id: event.id ?? null,
      summary: event.summary ?? null,
      start: event.start.dateTime,
      end: event.end.dateTime,
      blockedUntil: blockedEventEnd.toISOString()
    });
  }
}

if (conflicts.length > 0) {
  return [{
    json: {
      available: false,
      statusCode: 409,
      error: {
        code: "SLOT_UNAVAILABLE",
        message:
          "The requested appointment slot is no longer available."
      },
      conflicts
    }
  }];
}

return [{
  json: {
    available: true,
    statusCode: 200,
    booking: bookingData.booking,
    config: bookingData.config,
    requestedStartDateTime:
      bookingData.requestedStartDateTime,
    requestedEndDateTime:
      bookingData.requestedEndDateTime
  }
}];

const executionId = $execution.id;

const appointmentId = `apt_${executionId}`;

return [{
  json: {
    ...$json,
    appointmentId
  }
}];

const bookingData =
  $("Generate Appointment ID").first().json;

const event =
  $json;

return [{
  json: {
    success: true,

    appointment: {
      id: bookingData.appointmentId,

      date:
        bookingData.booking.date,

      start:
        bookingData.booking.start,

      end:
        bookingData.booking.end,

      timezone:
        bookingData.config.timezone,

      durationMinutes:
        bookingData.booking.durationMinutes,

      status:
        "CONFIRMED",

      customer:
        bookingData.booking.customer,

      calendarEventId:
        event.id ?? null
    }
  }
}];
